function initializeFocusReaderBounds(){const reader=$('#reader'),padding=parseFloat(getComputedStyle(reader).paddingLeft)||0,wide=reader.classList.contains('pdf-reader')||reader.classList.contains('media-reader');let width=wide?1400:980+padding*2;try{const saved=Number(localStorage.getItem('tcolib-focus-reader-width'));if(Number.isFinite(saved)&&saved>0)width=saved}catch{}focusReaderPreferredWidth=width;setFocusReaderWidth(focusReaderPreferredWidth,false);syncFocusWidthHandle()}
function finishFocusWidthDrag(){if(!focusWidthDrag)return;focusWidthDrag=null;document.body.classList.remove('focus-width-dragging');try{localStorage.setItem('tcolib-focus-reader-width',String(Math.round(focusReaderPreferredWidth)))}catch{}}
focusWidthHandle.addEventListener('pointerdown',event=>{if(!document.body.classList.contains('focus-mode')||event.button!==0)return;event.preventDefault();focusWidthDrag={pointerId:event.pointerId,startX:event.clientX,startWidth:parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--focus-reader-width'))};focusWidthHandle.setPointerCapture(event.pointerId);document.body.classList.add('focus-width-dragging')});
focusWidthHandle.addEventListener('pointermove',event=>{if(!focusWidthDrag||event.pointerId!==focusWidthDrag.pointerId)return;setFocusReaderWidth(focusWidthDrag.startWidth+2*(focusWidthDrag.startX-event.clientX))});
focusWidthHandle.addEventListener('pointerup',finishFocusWidthDrag);focusWidthHandle.addEventListener('pointercancel',finishFocusWidthDrag);focusWidthHandle.addEventListener('lostpointercapture',finishFocusWidthDrag);
focusWidthHandle.addEventListener('keydown',event=>{if(!document.body.classList.contains('focus-mode'))return;let next=focusReaderPreferredWidth;if(event.key==='ArrowLeft')next+=80;else if(event.key==='ArrowRight')next-=80;else if(event.key==='Home')next=1400;else if(event.key==='End')next=650;else return;event.preventDefault();setFocusReaderWidth(next)});
focusButton.addEventListener('click',()=>{const enabled=document.body.classList.toggle('focus-mode');focusButton.textContent=enabled?'退出专注':'专注阅读';focusButton.setAttribute('aria-pressed',String(enabled));syncFocusImageTools();if(enabled)initializeFocusReaderBounds();else{resetPreviewImageTransform();finishFocusWidthDrag();focusWidthHandle.hidden=true}});
$('#readerFavoriteToggle').addEventListener('click',async()=>{if(active){await toggleFavorite(active);syncReaderFavorite()}});
$('#exitReader').addEventListener('click',closeBook);
$('#initializeLibrary').addEventListener('click',initializeLibrary);
syncSizeSliderFill();
restoreDirectory();
loadFavorites();
window.addEventListener('resize',()=>{if(document.body.classList.contains('focus-mode')&&!focusWidthDrag){setFocusReaderWidth(focusReaderPreferredWidth,false);syncFocusWidthHandle()}if(!active||progressRestorePending)return;if(!readerResizing){readerResizing=true;resizeProgressTarget=lastProgressSnapshot}clearTimeout(resizeEndTimer);cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{const item=files.find(x=>x.path===active),type=item&&mediaType(item),body=$('#reader');if(!type&&item?.ext!=='.pdf'){const max=body.scrollHeight-body.clientHeight;body.style.scrollBehavior='auto';body.scrollTop=Math.max(0,resizeProgressTarget*max);requestAnimationFrame(()=>{body.style.scrollBehavior=''})}updateProgress()});resizeEndTimer=setTimeout(()=>{if(!active)return;const item=files.find(x=>x.path===active),type=item&&mediaType(item),body=$('#reader'),progress=resizeProgressTarget;if(!type&&item?.ext!=='.pdf'){const max=body.scrollHeight-body.clientHeight;body.style.scrollBehavior='auto';body.scrollTop=Math.max(0,progress*max)}requestAnimationFrame(()=>{body.style.scrollBehavior='';lastProgressSnapshot=progress;progressSnapshotReady=true;readerResizing=false;resizeProgressTarget=null;updateProgress();scheduleProgressSave()})},180)});
